// Simplified sketch of a page fault handler, not real kernel code

void handle_page_fault(int page_number) {
    if (ram_is_full()) {
        int victim_frame = choose_victim_frame();  // a page replacement algorithm decides this
        write_back_if_dirty(victim_frame);
        mark_page_invalid(frame_to_page(victim_frame));
    }
    int frame = load_page_from_disk(page_number);
    update_page_table(page_number, frame, VALID);
    resume_process();
}

